import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  MenuItem,
  Select,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';
import { COMPLIANCE_PANEL_STRINGS, formatCompliancePanelString } from '../../i18n/compliancePanelLocale';

type DsarQueueItem = {
  _id: string;
  userId?: string;
  type?: string;
  status?: string;
  description?: string;
  requestedAt?: string;
  daysOpen?: number | null;
  daysUntilDue?: number | null;
  overdue?: boolean;
  slaDueAt?: string;
};

type DsarSlaSummary = {
  slaDays?: number;
  overdueCount?: number;
  dueWithin7Days?: number;
  onTrackCount?: number;
};

const AdminDsarOpsPanel: React.FC<{ locale?: 'en' | 'hi' }> = ({ locale = 'en' }) => {
  const strings = COMPLIANCE_PANEL_STRINGS[locale];
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [requests, setRequests] = useState<DsarQueueItem[]>([]);
  const [openCount, setOpenCount] = useState(0);
  const [slaSummary, setSlaSummary] = useState<DsarSlaSummary | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [notes, setNotes] = useState<Record<string, string>>({});

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getAdminDsarQueue({ status: 'open', limit: 50 });
      setRequests((res?.data?.requests as DsarQueueItem[]) || []);
      setOpenCount(Number(res?.data?.openCount || 0));
      setSlaSummary((res?.data?.sla as DsarSlaSummary) || null);
    } catch (e) {
      setError(e instanceof Error ? e.message : strings.dsarLoadFailed);
    } finally {
      setLoading(false);
    }
  }, [strings.dsarLoadFailed]);

  useEffect(() => {
    void load();
  }, [load]);

  const updateStatus = async (id: string, status: string) => {
    setBusyId(id);
    try {
      await ApiService.updateAdminDsarRequest(id, {
        status,
        processingNotes: notes[id] || undefined,
      });
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : strings.dsarUpdateFailed);
    } finally {
      setBusyId(null);
    }
  };

  if (loading) {
    return <CircularProgress size={24} />;
  }

  return (
    <Card variant="outlined" sx={{ mt: 2 }}>
      <CardContent>
        <Typography variant="h6" gutterBottom>{strings.dsarTitle}</Typography>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 2 }}>
          <Chip label={formatCompliancePanelString(strings.dsarOpenCount, { count: openCount })} color={openCount > 0 ? 'warning' : 'success'} />
          {slaSummary ? (
            <>
              <Chip
                label={formatCompliancePanelString(strings.dsarOverdueCount, {
                  count: slaSummary.overdueCount ?? 0,
                  days: slaSummary.slaDays ?? 30,
                })}
                color={(slaSummary.overdueCount ?? 0) > 0 ? 'error' : 'default'}
                variant="outlined"
              />
              <Chip
                label={formatCompliancePanelString(strings.dsarDueSoonCount, { count: slaSummary.dueWithin7Days ?? 0 })}
                color={(slaSummary.dueWithin7Days ?? 0) > 0 ? 'warning' : 'default'}
                variant="outlined"
              />
              <Chip
                label={formatCompliancePanelString(strings.dsarOnTrackCount, { count: slaSummary.onTrackCount ?? 0 })}
                color="success"
                variant="outlined"
              />
            </>
          ) : null}
        </Stack>
        {error ? <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert> : null}
        {requests.length === 0 ? (
          <Alert severity="info">{strings.dsarEmptyQueue}</Alert>
        ) : (
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Type</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Requested</TableCell>
                <TableCell>SLA</TableCell>
                <TableCell>Notes</TableCell>
                <TableCell align="right">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {requests.map((entry) => (
                <TableRow key={entry._id}>
                  <TableCell>{entry.type}</TableCell>
                  <TableCell>{entry.status}</TableCell>
                  <TableCell>
                    {entry.requestedAt ? new Date(entry.requestedAt).toLocaleDateString() : '—'}
                  </TableCell>
                  <TableCell>
                    {entry.overdue ? (
                      <Chip size="small" label={formatCompliancePanelString(strings.dsarOverdueLabel, { days: Math.abs(entry.daysUntilDue ?? 0) })} color="error" />
                    ) : entry.daysUntilDue != null ? (
                      <Chip
                        size="small"
                        label={entry.daysUntilDue <= 7
                          ? formatCompliancePanelString(strings.dsarDueInDays, { days: entry.daysUntilDue })
                          : formatCompliancePanelString(strings.dsarDaysOpen, { days: entry.daysOpen ?? 0 })}
                        color={entry.daysUntilDue <= 7 ? 'warning' : 'default'}
                        variant="outlined"
                      />
                    ) : (
                      '—'
                    )}
                  </TableCell>
                  <TableCell>
                    <TextField
                      size="small"
                      placeholder={strings.dsarProcessingNote}
                      value={notes[entry._id] || ''}
                      onChange={(e) => setNotes((prev) => ({ ...prev, [entry._id]: e.target.value }))}
                    />
                  </TableCell>
                  <TableCell align="right">
                    <Stack direction="row" spacing={1} justifyContent="flex-end">
                      <Select
                        size="small"
                        value={entry.status || 'pending'}
                        onChange={(e) => void updateStatus(entry._id, String(e.target.value))}
                        disabled={busyId === entry._id}
                      >
                        <MenuItem value="pending">Pending</MenuItem>
                        <MenuItem value="in_progress">In progress</MenuItem>
                        <MenuItem value="completed">Completed</MenuItem>
                        <MenuItem value="rejected">Rejected</MenuItem>
                      </Select>
                      <Button
                        size="small"
                        variant="outlined"
                        disabled={busyId === entry._id}
                        onClick={() => void updateStatus(entry._id, 'completed')}
                      >
                        {strings.dsarCompleteButton}
                      </Button>
                    </Stack>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </CardContent>
    </Card>
  );
};

export default AdminDsarOpsPanel;
